CREATE TABLE `level_threshold` (
  `threshold_id` int NOT NULL AUTO_INCREMENT,
  `level_id` int NOT NULL,
  `min_score` int NOT NULL,
  `max_score` int NOT NULL,
  PRIMARY KEY (`threshold_id`),
  UNIQUE KEY `level_id` (`level_id`),
  CONSTRAINT `level_threshold_ibfk_1` FOREIGN KEY (`level_id`) REFERENCES `proficiency_level` (`level_id`) ON DELETE CASCADE,
  CONSTRAINT `level_threshold_chk_1` CHECK (((`min_score` >= 0) and (`max_score` <= 100))),
  CONSTRAINT `level_threshold_chk_2` CHECK ((`min_score` <= `max_score`))
